SELECT id,community_code AS communityCd,community_name AS communityName,community_place AS communityPlace,community_area AS communityArea,people_number AS peopleNumber,state,updateTime, ( SELECT COUNT(*) FROM communities
1=1
AND community_code = #{communityCd}
AND del_flag = 0
) AS total FROM communities
1=1
AND community_code = #{communityCd}
AND del_flag = 0
ORDER BY id LIMIT #{pageStart},#{pageSize}
